mapper.select:
select id, app_id, user_email, plan_id, base_quota, purchased_quota, consumed_quota, seed_user, status,
       last_grant_order_no, last_grant_at, version, created_at, updated_at
from billing_account
where app_id = #{appId}
  and user_email = #{userEmail}
limit 1

mapper.insert:
insert into billing_grant_record (
    id, order_no, app_id, user_email, plan_id, quota, amount_fen, payment_channel, status, created_at
) values (
    #{id}, #{orderNo}, #{appId}, #{userEmail}, #{planId}, #{quota}, #{amountFen}, #{paymentChannel}, #{status}, now()
)
on conflict (order_no) do nothing

insert into billing_usage_record (
    id, app_id, user_email, run_id, scene, quota_cost, created_at
) values (
    #{id}, #{appId}, #{userEmail}, #{runId}, #{scene}, #{quotaCost}, now()
)
on conflict (app_id, user_email, run_id) do nothing

mapper.update:
update billing_account
set consumed_quota = consumed_quota + #{quota},
    updated_at = now(),
    version = version + 1
where id = #{id}
  and (base_quota + purchased_quota - consumed_quota) >= #{quota}
